async function createPost(postData) {
  const apiUrl = "https://jsonplaceholder.typicode.com/posts";

  try {
    const response = await fetch(apiUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Accept": "application/json"
      },
      body: JSON.stringify(postData)
    });

    // CRITICAL: Fetch does NOT reject on HTTP 404 or 500 status codes!
    // Must check response.ok (status in the range 200-299)
    if (!response.ok) {
      throw new Error(`HTTP network error! Status: ${response.status}`);
    }

    const responseData = await response.json();
    console.log("Post created successfully:", responseData);
    return responseData;
  } catch (error) {
    console.error("Fetch operation failed:", error.message);
    throw error;
  }
}

createPost({ title: "Learning Web APIs", body: "Fetch makes HTTP simple.", userId: 1 });

const storageHelper = {
  // Automatically serializes objects to JSON strings
  set(key, value) {
    try {
      const serialized = JSON.stringify(value);
      localStorage.setItem(key, serialized);
    } catch (e) {
      console.error("Error saving to localStorage:", e);
    }
  },

  // Automatically deserializes JSON strings back into objects
  get(key, fallback = null) {
    try {
      const item = localStorage.getItem(key);
      return item ? JSON.parse(item) : fallback;
    } catch (e) {
      console.warn("Error parsing localStorage item:", e);
      return fallback;
    }
  },

  remove(key) {
    localStorage.removeItem(key);
  }
};

// Usage example:
storageHelper.set("userPreferences", { theme: "dark", fontSize: 16 });
const prefs = storageHelper.get("userPreferences");
console.log("Loaded preferences:", prefs);

function requestUserLocation() {
  if (!("geolocation" in navigator)) {
    console.warn("Geolocation is not supported by this browser.");
    return;
  }

  const options = {
    enableHighAccuracy: true,
    timeout: 5000,    // 5 seconds max wait
    maximumAge: 0     // Do not use cached position
  };

  function onSuccess(position) {
    const { latitude, longitude, accuracy } = position.coords;
    console.log(`Latitude: ${latitude}, Longitude: ${longitude}`);
    console.log(`Accuracy: within ${accuracy} meters.`);
  }

  function onError(error) {
    switch (error.code) {
      case error.PERMISSION_DENIED:
        console.error("User denied the request for Geolocation.");
        break;
      case error.POSITION_UNAVAILABLE:
        console.error("Location information is unavailable.");
        break;
      case error.TIMEOUT:
        console.error("The request to get user location timed out.");
        break;
    }
  }

  navigator.geolocation.getCurrentPosition(onSuccess, onError, options);
}

requestUserLocation();
